// Plain-language limits describe missing information, never product quality.
export const readingLimits = {
  price: { label: "Price not verified", detail: "No verified price for this size." },
  concentration: { label: "Individual amounts not verified", detail: "Manufacturer disclosure; not independently measured." },
  preparation: { label: "Different study preparation", detail: "Not a test of either compared serum." },
} as const;

export const supportLabels: Record<string, string> = {
  "Manufacturer label": "Manufacturer label",
  "Supplier information": "Supplier information",
  "Human ingredient study": "Human ingredient study",
  "Human formulation study": "Human formula study",
  "Human clinical trial": "Human trial",
  "Human pilot study": "Human pilot study",
  "Laboratory study": "Laboratory study",
  "Human case report": "Case report",
  "Expert safety assessment": "Safety assessment",
  "Regulatory safety opinion": "Regulatory safety opinion",
  "Regulatory guidance": "Regulatory guidance",
  "Manufacturer study summary": "Brand-reported study",
};

export const usesReadingContext = (id: string) => ["niod-vs-ordinary", "ordinary-ha-vs-copper"].includes(id);

import { evidence } from "@/lib/citations";
import { supportLabels } from "@/lib/reading-context";

// Quiet text identifies the source, without colored scores or quality badges.
export function EvidenceSupport({ ids, interpretation = false }: { ids: string[]; interpretation?: boolean }) {
  if (interpretation) return <p className="evidence-support">Editorial interpretation</p>;
  const labels = [...new Set(ids.map((id) => evidence.find((e) => e.sourceId === id)?.kind).filter((kind) => kind !== undefined).map((kind) => supportLabels[kind] ?? kind))];
  return <p className="evidence-support">{labels.length ? `Source type: ${labels.join(" · ")}` : "Editorial interpretation"}</p>;
}

import { Citations } from "./citations";
import type { CitationSet } from "@/lib/citations";
import type { Evaluation } from "@/lib/evaluations";
import { EvidenceSupport } from "./evidence-support";
import { readingLimits, usesReadingContext } from "@/lib/reading-context";

// The shopper needs a brief decision summary, with research detail on demand.
// Reuse DM Sans, existing ink/mineral tokens, border-only panels and 16/24px
// spacing; native disclosures preserve keyboard and no-JavaScript access.
export function ComparisonEvaluation({
  evaluation,
  citations,
  compact = false,
}: {
  evaluation: Evaluation;
  citations: CitationSet;
  compact?: boolean;
}) {
  const clarify = usesReadingContext(evaluation.comparisonId);
  return (
    <section
      id={compact ? "research-evidence" : "before-you-buy"}
      className={compact ? "reader-evidence" : "section"}
      aria-labelledby="evaluation-title"
    >
      <span className="eyebrow">A CRITICAL LOOK AT THE EVIDENCE</span>
      <h2 id="evaluation-title">
        {compact ? "Evidence, explained." : evaluation.title}
      </h2>
      {!compact && <p className="section-intro">{evaluation.summary}</p>}
      {!compact && (
        <p className="small">
          Draft evidence synthesis · Sources checked {evaluation.checkedAt}.
          Human editorial and qualified scientific review pending. No
          finished-product testing or personal medical advice.
        </p>
      )}
      {clarify && <details className="support-key">
        <summary>What do the source labels mean?</summary>
        <p>Human studies describe what happened in their participants and tested preparation. Laboratory studies examine a model, not clinical results in shoppers. Case reports describe individual events, not how often they occur.</p>
        <p>Safety assessments review specified uses and concentrations. Manufacturer labels identify recorded product facts. Neither is a guarantee of results or individual tolerance. Source type is not a quality score.</p>
      </details>}
      <div className="question-grid evaluation-grid">
        {evaluation.sections.map((section) => (
          <article
            className="panel evaluation-card"
            id={`evaluation-${section.id}`}
            key={section.id}
          >
            <h3>{section.title}</h3>
            {clarify && <EvidenceSupport ids={section.paragraphs.flatMap((p) => p.sourceIds)} />}
            <p>
              <strong>{section.conclusion}</strong>
              <Citations
                set={citations}
                claim={`evaluation-conclusion-${section.id}`}
              />
            </p>
            <details>
              <summary>Read the evidence and what it means</summary>
              {section.paragraphs.map((paragraph, index) => (
                <div key={index}>
                  {clarify ? <EvidenceSupport ids={paragraph.sourceIds} interpretation={paragraph.kind === "interpretation"} /> : <span className="reference-kind">
                    {paragraph.kind === "interpretation"
                      ? "What this means for your decision · editorial interpretation"
                      : "What the research reports"}
                  </span>}
                  <p>
                    {paragraph.text}
                    <Citations
                      set={citations}
                      claim={`evaluation-${section.id}-${index}`}
                    />
                  </p>
                  {clarify && paragraph.kind === "evidence" && paragraph.sourceIds.some((id) => ["argireline-trial", "kraeling-penetration"].includes(id)) && <p className="data-limit-inline"><strong>{readingLimits.preparation.label}.</strong> {readingLimits.preparation.detail}</p>}
                </div>
              ))}
            </details>
          </article>
        ))}
      </div>
      <details className="panel section label-provenance">
        <summary>
          Which label facts connect this research to these products?
        </summary>
        {clarify && <EvidenceSupport ids={evaluation.labelSourceIds} />}
        <p>
          {evaluation.labelContext}
          <Citations set={citations} claim="evaluation-labels" />
        </p>
        <p className="small">
          Manufacturer links establish ingredient presence only. Scientific
          references support the research statements above. Formulas can change;
          check your purchased packaging.
        </p>
      </details>
    </section>
  );
}

"use client";

import { useId, useState, type ReactNode } from "react";
import Link from "next/link";
import { ArrowUpRight } from "lucide-react";
import { brandName, type Product } from "@/lib/data";
import {
  comparisonRows,
  visibleComparisonRows,
  type ComparisonValue,
} from "@/lib/comparison";
import { productPath } from "@/lib/config";
import { Bottle } from "./ui";
import { IngredientHelp } from "./ingredient-help";

function FactValue({
  value,
  explainIngredients = false,
  comparisonQuery,
}: {
  value: ComparisonValue;
  explainIngredients?: boolean;
  comparisonQuery?: string;
}) {
  return (
    <>
      {value.href ? (
        <a
          className="matrix-source"
          href={value.href}
          target="_blank"
          rel="noopener noreferrer"
        >
          {value.text} <ArrowUpRight size={15} />
        </a>
      ) : (
        value.text && (
          <span className={value.missing ? "matrix-missing" : "matrix-value"}>
            {value.text}
          </span>
        )
      )}
      {value.items && (
        <ul className="matrix-list">
          {value.items.map((item) => (
            <li key={item}>
              {explainIngredients ? (
                <IngredientHelp name={item} comparisonQuery={comparisonQuery} />
              ) : (
                item
              )}
            </li>
          ))}
        </ul>
      )}
      {value.date && (
        <small>
          {value.href ? "Label checked" : "Price recorded"}{" "}
          <time dateTime={value.date}>{value.date}</time>
        </small>
      )}
      {value.note && <small>{value.note}</small>}
      {value.limitLabel && <small className="data-limit-inline"><strong>{value.limitLabel}</strong></small>}
    </>
  );
}

export function ComparisonGrid({
  a,
  b,
  controls,
  clarifyLimits = false,
}: {
  a: Product;
  b: Product;
  controls?: [ReactNode, ReactNode];
  clarifyLimits?: boolean;
}) {
  const [differencesOnly, setDifferencesOnly] = useState(false);
  const id = useId();
  const rows = comparisonRows(a, b, clarifyLimits);
  const visible = visibleComparisonRows(rows, differencesOnly);
  const groups = [...new Set(visible.map((row) => row.group))];
  return (
    <div className="matrix-workspace">
      <div className="matrix-tools">
        <label className="matrix-filter">
          <input
            type="checkbox"
            checked={differencesOnly}
            onChange={(event) => setDifferencesOnly(event.target.checked)}
          />{" "}
          Show only differences
        </label>
        <span role="status">
          {differencesOnly
            ? `${rows.length - visible.length} matching rows hidden · Limits and sources kept visible`
            : "All recorded details · No product rankings"}
        </span>
      </div>
      <p id={`${id}-note`} className="matrix-context">
        Compare recorded facts side by side. Missing information is not a
        negative rating.
      </p>
      <table
        className="visual-comparison"
        role="table"
        aria-describedby={`${id}-note`}
      >
        <caption className="matrix-caption">
          Peptide serum label comparison: {brandName(a)} and {brandName(b)}
        </caption>
        <colgroup>
          <col className="matrix-label-column" />
          <col />
          <col />
        </colgroup>
        <thead role="rowgroup">
          <tr role="row">
            <th className="matrix-corner" scope="col" role="columnheader">
              Compare the details
              <span>
                Two products.
                <br />
                The same questions.
              </span>
            </th>
            {[a, b].map((p, index) => (
              <th
                scope="col"
                role="columnheader"
                id={`${id}-product-${index}`}
                key={index}
              >
                {controls ? (
                  controls[index]
                ) : (
                  <div className="matrix-static-product">
                    <span className="slot-marker">
                      {index === 0 ? "A" : "B"}
                    </span>
                    <Bottle product={p} />
                    <strong>{brandName(p)}</strong>
                    <Link href={productPath(p.slug)}>{p.name}</Link>
                  </div>
                )}
              </th>
            ))}
          </tr>
        </thead>
        {groups.map((group) => (
          <tbody role="rowgroup" key={group}>
            <tr className="matrix-group" role="row">
              <th colSpan={3} role="columnheader" scope="colgroup">
                {group}
              </th>
            </tr>
            {visible
              .filter((row) => row.group === group)
              .map((row) => (
                <tr
                  className="matrix-row"
                  role="row"
                  data-comparison-row={row.id}
                  key={row.id}
                >
                  <th id={`${id}-${row.id}`} scope="row" role="rowheader">
                    {row.label}
                    {row.id === "peptides" && (
                      <p className="matrix-row-help">
                        Peptides are small chains of the building blocks used in
                        proteins. Their names identify ingredients, not quality
                        scores. Open an explanation to learn what each one
                        means.
                      </p>
                    )}
                    {row.id === "concentrations" && (
                      <p className="matrix-row-help">
                        A formula is the whole mix. A blend percentage does not
                        tell us the amount of every ingredient.
                      </p>
                    )}
                  </th>
                  {row.values.map((value, index) => (
                    <td
                      role="cell"
                      key={index}
                      headers={`${id}-${row.id} ${id}-product-${index}`}
                    >
                      <span
                        className="matrix-mobile-identity"
                        aria-hidden="true"
                      >
                        <span className="slot-marker">
                          {index === 0 ? "A" : "B"}
                        </span>
                        {brandName(index === 0 ? a : b)}
                      </span>
                      <FactValue
                        value={value}
                        explainIngredients={row.id === "peptides"}
                        comparisonQuery={new URLSearchParams({
                          a: a.id,
                          b: b.id,
                        }).toString()}
                      />
                    </td>
                  ))}
                </tr>
              ))}
          </tbody>
        ))}
      </table>
      <p className="matrix-footnote">
        Prices are dated USD observations. Ingredient selections are incomplete;
        matching names do not establish equivalent formulas or results.
      </p>
    </div>
  );
}

import { brandName, priceFor, sourceFor, type Product } from "./data";
import { compareLabels, money, normalize } from "./math";
import { readingLimits } from "./reading-context";

export function costInsight(a: number | null, b: number | null) {
  if (a === null || b === null) return { kind: "missing" as const };
  if (a === b) return { kind: "equal" as const };
  const lower = a < b ? ("a" as const) : ("b" as const);
  // Percentage is relative to the more expensive product, so zero-price products are supported.
  return {
    kind: "different" as const,
    lower,
    percent: ((Math.max(a, b) - Math.min(a, b)) / Math.max(a, b)) * 100,
  };
}
export function comparisonFacts(a: Product, b: Product) {
  const observations = [priceFor(a), priceFor(b)] as const;
  const costs = observations.map((p) =>
    p ? normalize(p.price, p.size, p.sizeUnit) : null,
  );
  return {
    observations,
    costs,
    labels: compareLabels(a.ingredientList, b.ingredientList),
    cost: costInsight(costs[0]?.perMl ?? null, costs[1]?.perMl ?? null),
  };
}
export const volumeLabel = (p: Product) =>
  `${p.volume} ${p.volumeUnit === "ml" ? "mL" : "US fl oz"}`;

export type ComparisonValue = {
  text: string;
  note?: string;
  items?: string[];
  href?: string;
  date?: string;
  missing?: boolean;
  limitLabel?: string;
};
export type ComparisonRow = {
  id: string;
  group: string;
  label: string;
  values: [ComparisonValue, ComparisonValue];
  different: boolean;
  essential?: boolean;
};

// Unknown values are never considered proof of equality. Limits and sources
// remain visible even when a shopper asks to hide matching recorded facts.
export function comparisonRows(a: Product, b: Product, clarifyLimits = false): ComparisonRow[] {
  const pair = [a, b] as const;
  const facts = comparisonFacts(a, b);
  const values = (
    render: (p: Product, i: number) => ComparisonValue,
  ): [ComparisonValue, ComparisonValue] => [render(a, 0), render(b, 1)];
  const names = (p: Product) =>
    [...new Set(p.ingredientList.map((name) => name.trim().toLowerCase()))]
      .sort()
      .join("|");
  return [
    {
      id: "size",
      group: "Product basics",
      label: "Presentation",
      different: a.volume !== b.volume || a.volumeUnit !== b.volumeUnit,
      values: values((p) => ({ text: volumeLabel(p) })),
    },
    {
      id: "format",
      group: "Product basics",
      label: "Format",
      different: a.category !== b.category,
      values: values((p) => ({ text: p.category })),
    },
    {
      id: "usage",
      group: "Product basics",
      label: "How the brand says to use it",
      different: a.usageSummary !== b.usageSummary,
      essential: true,
      values: values((p) => ({
        text:
          p.usageSummary ??
          "Directions not recorded. Read the manufacturer's current instructions.",
        missing: !p.usageSummary,
        note: "Manufacturer directions, not a personalized routine.",
      })),
    },
    {
      id: "price",
      group: "Price & value",
      label: "Recorded price",
      different: facts.observations[0]?.price !== facts.observations[1]?.price,
      essential: facts.observations.some((price) => !price),
      values: values((_, i) => {
        const price = facts.observations[i];
        return price
          ? {
              text: `${money(price.price)} USD`,
              note: "Excludes tax and shipping.",
              date: price.verifiedAt,
            }
          : {
              text: clarifyLimits ? readingLimits.price.label : "Not recorded",
              note: readingLimits.price.detail,
              missing: true,
            };
      }),
    },
    {
      id: "unit-cost",
      group: "Price & value",
      label: "Price per mL",
      different: facts.costs[0]?.perMl !== facts.costs[1]?.perMl,
      essential: facts.costs.some((cost) => !cost),
      values: values((_, i) =>
        facts.costs[i]
          ? { text: `${money(facts.costs[i]!.perMl)} / mL` }
          : {
              text: clarifyLimits ? readingLimits.price.label : "Not available",
              note: "Requires a verified price for this size.",
              missing: true,
            },
      ),
    },
    {
      id: "peptides",
      group: "What it contains and what it means",
      label: "Peptides, explained",
      different: names(a) !== names(b),
      values: values((p) => ({
        text: "",
        items: p.ingredientList,
        note: p.ingredientListScope,
      })),
    },
    {
      id: "concentrations",
      group: "What it contains and what it means",
      label: "How much of each ingredient?",
      different: a.concentrationDisclosure !== b.concentrationDisclosure,
      essential: true,
      values: values((p) => ({
        text: p.concentrationExplanation,
        limitLabel: clarifyLimits ? readingLimits.concentration.label : undefined,
        note: readingLimits.concentration.detail,
      })),
    },
    {
      id: "unknowns",
      group: "Sources & limits",
      label: "What we still cannot know",
      different: false,
      essential: true,
      values: values((_, i) => ({
        text: "Not established",
        missing: true,
        items: [
          ...(!facts.observations[i] ? ["Verified price for this size"] : []),
          "Complete ingredient list in this catalog",
          "Independent comparative effectiveness",
        ],
      })),
    },
    {
      id: "sources",
      group: "Sources & limits",
      label: "Label source",
      different: pair[0].sourceId !== pair[1].sourceId,
      essential: true,
      values: values((p) => ({
        text: `${brandName(p)} manufacturer label`,
        href: sourceFor(p).url,
        date: p.lastVerifiedAt,
        note: "Label checked; not a clinical review.",
      })),
    },
  ];
}

export function visibleComparisonRows(
  rows: ComparisonRow[],
  differencesOnly: boolean,
) {
  return differencesOnly
    ? rows.filter((row) => row.different || row.essential)
    : rows;
}
